use std::{cell::Cell, rc::Rc};

use freya::prelude::*;
use freya_core::{element::ElementExt, tree::DiffModifies};
use freya_testing::prelude::*;

struct DiffProbe(Rc<Cell<usize>>);

impl ElementExt for DiffProbe {
    fn diff(&self, _other: &Rc<dyn ElementExt>) -> DiffModifies {
        self.0.set(self.0.get() + 1);
        DiffModifies::empty()
    }
}

struct StatefulChild {
    comparisons: Rc<Cell<usize>>,
    renders: Rc<Cell<usize>>,
    value: State<usize>,
    key: DiffKey,
}

impl PartialEq for StatefulChild {
    fn eq(&self, other: &Self) -> bool {
        self.comparisons.set(self.comparisons.get() + 1);
        self.value == other.value && self.key == other.key
    }
}

impl KeyExt for StatefulChild {
    fn key_mut(&mut self) -> &mut DiffKey {
        &mut self.key
    }
}

impl Component for StatefulChild {
    fn render(&self) -> impl IntoElement {
        self.renders.set(self.renders.get() + 1);
        format!("Value {}", self.value.read())
    }

    fn render_key(&self) -> DiffKey {
        self.key.clone().or(self.default_key())
    }
}

#[test]
fn scrolling_skips_children_but_preserves_independent_updates() {
    let diffs = Rc::new(Cell::new(0));
    let comparisons = Rc::new(Cell::new(0));
    let renders = Rc::new(Cell::new(0));
    let (mut test, (mut controller, mut value)) = TestingRunner::new(
        {
            let diffs = diffs.clone();
            let comparisons = comparisons.clone();
            let renders = renders.clone();
            move || {
                let controller = use_consume::<ScrollController>();
                let value = use_consume::<State<usize>>();
                ScrollView::new_controlled(controller)
                    .child(StatefulChild {
                        comparisons: comparisons.clone(),
                        renders: renders.clone(),
                        value,
                        key: DiffKey::None,
                    })
                    .children((0..2000).map(|index| {
                        rect().key(index).height(Size::px(20.)).child(Element::Element {
                            key: DiffKey::None,
                            element: Rc::new(DiffProbe(diffs.clone())),
                            elements: Vec::new(),
                        })
                    }))
            }
        },
        (500., 500.).into(),
        |runner| {
            (
                runner.provide_root_context(|| ScrollController::new(0, 0)),
                runner.provide_root_context(|| State::create(0usize)),
            )
        },
        1.,
    );
    test.sync_and_update();
    diffs.set(0);
    comparisons.set(0);
    renders.set(0);

    test.run_in(|| controller.scroll_to_y(-100));
    test.sync_and_update();
    test.run_in(|| controller.scroll_to_y(-200));
    test.sync_and_update();
    assert_eq!(test.run_in(|| controller.position().y), -200.);
    assert_eq!(diffs.get(), 0);
    assert_eq!(comparisons.get(), 0);
    assert_eq!(renders.get(), 0);

    test.run_in(|| value.set(1));
    test.sync_and_update();
    assert_eq!(renders.get(), 1);
    assert_eq!(diffs.get(), 0);
    assert!(test.find(|_, element| {
        Label::try_downcast(element).filter(|label| label.text == "Value 1")
    }).is_some());
}

#[test]
fn shared_scroll_children_can_be_added_removed_and_reordered() {
    let (mut test, mut items) = TestingRunner::new(
        || {
            let items = use_consume::<State<Vec<usize>>>();
            ScrollView::new().show_scrollbar(false).children(items.read().iter().map(|index| {
                rect().key(*index).height(Size::px(100.)).child(format!("Item {index}"))
            }))
        },
        (500., 500.).into(),
        |runner| runner.provide_root_context(|| State::create(vec![0usize, 1, 2, 3, 4, 5])),
        1.,
    );
    test.sync_and_update();
    test.run_in(|| items.set(vec![5, 0, 6]));
    test.sync_and_update();
    let mut labels = test.find_many(|node, element| {
        Label::try_downcast(element).map(|label| (node.layout().area.min_y(), label.text.to_string()))
    });
    labels.sort_by(|first, second| first.0.total_cmp(&second.0));
    assert_eq!(labels, vec![(0., "Item 5".to_string()), (100., "Item 0".to_string()), (200., "Item 6".to_string())]);
}

#[test]
fn editing_cloned_scroll_children_uses_copy_on_write() {
    let mut test = launch_test(|| {
        let original = ScrollView::new().child("Original");
        let mut edited = original.clone();
        edited.children_mut().push("Added".into_element());
        rect().child(original).child(edited)
    });
    test.sync_and_update();
    let labels = test.find_many(|_, element| Label::try_downcast(element).map(|label| label.text.to_string()));
    assert_eq!(labels.iter().filter(|text| *text == "Original").count(), 2);
    assert_eq!(labels.iter().filter(|text| *text == "Added").count(), 1);
}

