        nodes.extend((10..10 + row_count).map(|index| {
            let mut row = Node::new(row_role);
            let top = (index - 10) as f64 * 80.;
            row.set_bounds(Rect::new(0., top, 700., top + 80.));
            (NodeId(index), row)
        }));
        let context = AppContext::new(None);
        let mut adapter = Adapter::new(
            &context,
            NoOpCallback,
            TreeUpdate {
                tree_id: TreeId::ROOT,
                nodes,
                tree: Some(TreeInfo::new(NodeId(0))),
                focus: NodeId(0),
            },
            true,
            WindowBounds::default(),
            NoOpActionHandler,
        );
        let started = Instant::now();
        let iterations = std::env::var("SCROLL_PERF_ITERATIONS")
            .ok()
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or(100);
        for index in 0..iterations {
            scroll.set_scroll_y(-((index + 1) as f64));
            let top = index as f64;
            scrollbar.set_bounds(Rect::new(690., top, 700., top + 20.));
            let mut nodes = vec![(NodeId(2), scroll.clone()), (NodeId(5), scrollbar.clone())];
            if change_children {
                let first = if index % 2 == 0 { 11 } else { 10 };
                content.set_children((first..10 + row_count).map(NodeId).collect::<Vec<_>>());
                nodes.push((NodeId(4), content.clone()));
                if first == 10 {
                    let mut row = Node::new(row_role);
                    row.set_bounds(Rect::new(0., 0., 700., 80.));
                    nodes.push((NodeId(10), row));
                }
            }
            adapter.update(TreeUpdate {
                tree_id: TreeId::ROOT,
                nodes,
                tree: None,
                focus: NodeId(0),
            });
        }
        println!("{row_role:?}, change_children={change_children}: {:?} per update", started.elapsed() / iterations);
    }
}

